{{pins}}
#include <Servo.h>

Servo dial;
int lastAngle = -1;

void setup() {
  dial.attach(SERVO_PIN);
  Serial.begin(9600);
}

void loop() {
  int knob = analogRead(POT_PIN);
  int angle = map(knob, 0, ANALOG_MAX, 0, 180);
  if (abs(angle - lastAngle) > 2) {  // only when it really moved
    dial.write(angle);
    Serial.print("Angle: ");
    Serial.println(angle);
    lastAngle = angle;
  }
  delay(15);
}
